'use strict';
// Original editorial paraphrases. References use the Douay–Rheims/Vulgate
// numbering of the pinned engDRA text, never automatically aligned WEB verses.
const rows = [];
function add(key, names, roles, summary, refs, bibleId = null, aliases = []) {
  rows.push({ key, names: names.split('|'), roles: roles.split('|'), summary: summary.split('|'), refs: refs.split(';'), bibleId, aliases });
}

// Tobit: the source calls both father and son Tobias. The two Annas and the
// Achior in this book also remain separate from similarly named people.
add('tobit', 'Tobit|Tobit|Tobit', 'Vader en balling|Father and exile|Père et exilé', 'Tobit helpt mede-ballingen en begraaft de doden; in deze editie heet hij Tobias, evenals zijn zoon.|Tobit helps fellow exiles and buries the dead; this edition calls him Tobias, like his son.|Tobit aide les autres exilés et ensevelit les morts ; cette édition le nomme Tobias, comme son fils.', 'TOB 1:1-9;TOB 1:19-22;TOB 14:1-5', null, ['Tobias de oudere', 'Tobias the elder']);
add('tobias', 'Tobias|Tobias|Tobie', 'Zoon en reiziger|Son and traveller|Fils et voyageur', 'Tobias reist namens zijn vader Tobit en trouwt met Sara; hij is een andere persoon dan zijn gelijknamige vader.|Tobias travels on behalf of his father Tobit and marries Sarah; he is distinct from his father of the same name.|Tobie voyage pour son père Tobit et épouse Sara ; il est distinct de son père du même nom.', 'TOB 1:9;TOB 7:10-17;TOB 8:4-10', null, ['Tobias de jongere', 'Tobiah']);
add('anna-tobit', 'Anna, vrouw van Tobit|Anna, wife of Tobit|Anna, épouse de Tobit', 'Moeder van Tobias|Mother of Tobias|Mère de Tobie', 'Anna is Tobits vrouw en Tobias’ moeder; zij onderhoudt het gezin met weefwerk.|Anna is Tobit’s wife and Tobias’s mother; she supports the household through weaving.|Anna est l’épouse de Tobit et la mère de Tobie ; elle fait vivre la famille par son tissage.', 'TOB 1:9;TOB 2:19-23');
add('sarah-tobit', 'Sara, dochter van Raguël|Sarah, daughter of Raguel|Sara, fille de Ragouël', 'Biddende bruid|Praying bride|Épouse en prière', 'Sara bidt in haar verdriet en trouwt met Tobias; zij is niet de aartsmoeder Sara uit Genesis.|Sarah prays in her distress and marries Tobias; she is distinct from the matriarch Sarah in Genesis.|Sara prie dans sa détresse et épouse Tobie ; elle est distincte de la matriarche Sara de la Genèse.', 'TOB 3:7-15;TOB 7:10-17;TOB 8:4-10', null, ['Sarah', 'Sarra']);
add('raguel', 'Raguël|Raguel|Ragouël', 'Vader van Sara|Father of Sarah|Père de Sara', 'Raguël ontvangt Tobias, stemt in met diens huwelijk met Sara en dankt God voor hun veiligheid.|Raguel welcomes Tobias, agrees to his marriage to Sarah and thanks God for their safety.|Ragouël accueille Tobie, consent à son mariage avec Sara et remercie Dieu de les avoir préservés.', 'TOB 7:1-17;TOB 8:15-20', null, ['Raguel']);
add('anna-raguel', 'Anna, vrouw van Raguël|Anna, wife of Raguel|Anna, épouse de Ragouël', 'Moeder van Sara|Mother of Sarah|Mère de Sara', 'Sara’s moeder heet Anna in de Douay–Rheims; zij troost haar dochter voor de bruiloft en is niet Tobits vrouw Anna.|Sarah’s mother is called Anna in the Douay–Rheims; she comforts her daughter before the wedding and is distinct from Tobit’s wife Anna.|La mère de Sara est nommée Anna dans la Douay–Rheims ; elle console sa fille avant les noces et se distingue de l’épouse de Tobit.', 'TOB 7:2;TOB 7:8;TOB 7:18-20');
add('gabael', 'Gabaël|Gabael|Gabaël', 'Bewaarder van het geld|Keeper of the money|Dépositaire de l’argent', 'Gabaël bewaart Tobits geld en komt naar de bruiloft van Tobias nadat het geld is opgehaald.|Gabael holds Tobit’s money and attends Tobias’s wedding after the money is collected.|Gabaël garde l’argent de Tobit et assiste aux noces de Tobie après sa restitution.', 'TOB 1:16-17;TOB 9:3-8', null, ['Gabelus']);
add('achior-tobit', 'Achior, verwant van Tobit|Achior, kinsman of Tobit|Achior, parent de Tobit', 'Verwant van Tobit|Kinsman of Tobit|Parent de Tobit', 'Deze Achior verheugt zich met Nabath over Tobits herstel; hij wordt niet samengevoegd met de Ammoniet uit Judit.|This Achior rejoices with Nabath over Tobit’s recovery; he is not merged with the Ammonite in Judith.|Cet Achior se réjouit avec Nabath de la guérison de Tobit ; il n’est pas fusionné avec l’Ammonite de Judith.', 'TOB 11:20');
add('nabath', 'Nabath|Nabath|Nabath', 'Verwant van Tobit|Kinsman of Tobit|Parent de Tobit', 'Nabath verschijnt met Achior onder de verwanten die zich over Tobits herstel verheugen.|Nabath appears with Achior among the relatives rejoicing over Tobit’s recovery.|Nabath figure avec Achior parmi les parents qui se réjouissent de la guérison de Tobit.', 'TOB 11:20');
add('sennacherib', 'Sanherib|Sennacherib|Sennachérib', 'Koning van Assyrië|King of Assyria|Roi d’Assyrie', 'Tobit beschrijft Sanheribs vervolging en de gevaren van het begraven van de slachtoffers.|Tobit describes Sennacherib’s persecution and the dangers of burying its victims.|Tobit décrit la persécution de Sennachérib et les dangers liés à l’ensevelissement des victimes.', 'TOB 1:18-24', 'step-H5576', ['Sennacherib']);

// Judith is indexed as a literary narrative. Its Assyrian king is not silently
// identified with the historical Babylonian king in the existing atlas.
add('judith', 'Judit|Judith|Judith', 'Weduwe en bevrijdster|Widow and deliverer|Veuve et libératrice', 'Judit verzet zich tegen overgave en doodt Holofernes om haar stad te bevrijden; zij is niet Esaus vrouw Judit.|Judith opposes surrender and kills Holofernes to deliver her city; she is distinct from Esau’s wife Judith.|Judith s’oppose à la reddition et tue Holopherne pour délivrer sa ville ; elle est distincte de l’épouse d’Ésaü.', 'JDT 8:1-10;JDT 13:6-11;JDT 16:26', null, ['Judith']);
add('manasseh-judith', 'Manasse, man van Judit|Manasseh, husband of Judith|Manassé, époux de Judith', 'Overleden echtgenoot|Deceased husband|Époux décédé', 'Judit wordt voorgesteld als de weduwe van Manasse, die tijdens de gerstoogst stierf.|Judith is introduced as the widow of Manasseh, who died during the barley harvest.|Judith est présentée comme la veuve de Manassé, mort pendant la moisson de l’orge.', 'JDT 8:2-4', null, ['Manasses']);
add('holofernes', 'Holofernes|Holofernes|Holopherne', 'Legerbevelhebber|Army commander|Chef de l’armée', 'Holofernes voert het leger van de koning aan en wordt tijdens het beleg door Judit gedood.|Holofernes commands the king’s army and is killed by Judith during the siege.|Holopherne commande l’armée du roi et est tué par Judith pendant le siège.', 'JDT 2:4-7;JDT 13:6-10');
add('achior-judith', 'Achior, de Ammoniet|Achior the Ammonite|Achior l’Ammonite', 'Getuige en bekeerling|Witness and convert|Témoin et converti', 'Achior waarschuwt Holofernes over Israëls God en sluit zich na Judits overwinning bij Israël aan.|Achior warns Holofernes about Israel’s God and joins Israel after Judith’s victory.|Achior avertit Holopherne au sujet du Dieu d’Israël et rejoint Israël après la victoire de Judith.', 'JDT 5:5-21;JDT 14:6');
add('ozias-judith', 'Uzzia van Betulia|Uzziah of Bethulia|Ozias de Béthulie', 'Stadsbestuurder|City leader|Chef de la ville', 'Uzzia ontvangt Achior en vertegenwoordigt Betulia tijdens het beleg; Judit spreekt hem aan op zijn ultimatum.|Uzziah welcomes Achior and represents Bethulia during the siege; Judith challenges his ultimatum.|Ozias accueille Achior et représente Béthulie pendant le siège ; Judith conteste son ultimatum.', 'JDT 6:11;JDT 6:19;JDT 7:23;JDT 8:9-10', null, ['Ozias']);
add('chabri', 'Chabri|Chabri|Chabri', 'Oudste van Betulia|Elder of Bethulia|Ancien de Béthulie', 'Chabri is een van de oudsten die Judit bij zich laat komen om hun besluit te bespreken.|Chabri is one of the elders Judith summons to discuss their decision.|Chabri est l’un des anciens que Judith fait venir pour discuter de leur décision.', 'JDT 8:9-10');
add('charmi', 'Charmi|Charmi|Charmi', 'Oudste van Betulia|Elder of Bethulia|Ancien de Béthulie', 'Charmi wordt bij de leiders van Betulia genoemd en luistert naar Judits kritiek op overgave.|Charmi is named among Bethulia’s leaders and hears Judith’s criticism of surrender.|Charmi est nommé parmi les chefs de Béthulie et entend la critique de Judith contre la reddition.', 'JDT 6:11;JDT 8:9-10', null, ['Gothoniel']);
add('eliachim', 'Eljakim, priester in Judit|Eliachim, priest in Judith|Éliaqim, prêtre de Judith', 'Priester|Priest|Prêtre', 'De priester Eljakim geeft aanwijzingen voor de verdediging en roept Israël tot gebed op.|The priest Eliachim gives instructions for the defence and calls Israel to prayer.|Le prêtre Éliaqim donne des instructions pour la défense et appelle Israël à la prière.', 'JDT 4:5-10', null, ['Eliachim']);
add('bagoas', 'Bagoas|Bagoas|Bagoas', 'Hofdienaar van Holofernes|Attendant of Holofernes|Serviteur d’Holopherne', 'Bagoas, in deze editie Vagao, nodigt Judit namens Holofernes uit voor het feest.|Bagoas, called Vagao in this edition, invites Judith to the feast on Holofernes’s behalf.|Bagoas, nommé Vagao dans cette édition, invite Judith au banquet au nom d’Holopherne.', 'JDT 12:10-13', null, ['Vagao']);
add('arphaxad-judith', 'Arpaksad, koning van de Meden|Arphaxad, king of the Medes|Arphaxad, roi des Mèdes', 'Koning in Judit|King in Judith|Roi dans Judith', 'Het verhaal begint met Arpaksads vestingbouw en zijn nederlaag tegenover de Assyrische koning.|The narrative begins with Arphaxad’s fortifications and his defeat by the Assyrian king.|Le récit commence par les fortifications d’Arphaxad et sa défaite devant le roi assyrien.', 'JDT 1:1-6', null, ['Arphaxad']);
add('nebuchadnezzar-judith', 'Nebukadnessar in Judit|Nebuchadnezzar in Judith|Nabuchodonosor dans Judith', 'Assyrische koning in het verhaal|Assyrian king in the narrative|Roi assyrien du récit', 'Judit situeert deze koning in Nineve als heerser van Assyrië; deze verhaalrol is niet stilzwijgend met de Babylonische koning samengevoegd.|Judith places this king in Nineveh as ruler of Assyria; this narrative role is not silently merged with the Babylonian king.|Judith situe ce roi à Ninive comme souverain d’Assyrie ; ce rôle narratif n’est pas fusionné sans réserve avec le roi babylonien.', 'JDT 1:5-6;JDT 2:4-7', null, ['Nabuchodonosor']);

// Wisdom's narrator is unnamed: a Solomonic literary voice is not an explicit
// personal identification in the text.
add('wisdom-narrator', 'Koninklijke verteller van Wijsheid|Royal narrator of Wisdom|Narrateur royal de la Sagesse', 'Naamloze wijsheidsleraar|Unnamed wisdom teacher|Maître de sagesse anonyme', 'De ik-figuur beschrijft zichzelf als sterfelijke koning en bidt om wijsheid; de geciteerde tekst noemt hem niet Salomo.|The speaker describes himself as a mortal king and prays for wisdom; the cited text does not name him Solomon.|Le locuteur se présente comme un roi mortel et demande la sagesse ; le texte cité ne le nomme pas Salomon.', 'WIS 7:1-7;WIS 9:7-12');

add('ben-sira', 'Jezus Sirach|Jesus ben Sira|Jésus ben Sira', 'Wijsheidsleraar|Wisdom teacher|Maître de sagesse', 'Het boek noemt Jezus, zoon van Sirach, als schrijver van onderwijs over wijsheid; hij is niet Jezus Christus.|The book names Jesus son of Sirach as the writer of instruction in wisdom; he is not Jesus Christ.|Le livre nomme Jésus, fils de Sirach, comme auteur d’un enseignement de sagesse ; il n’est pas Jésus Christ.', 'SIR 50:29-31', null, ['Ben Sira', 'Jezus ben Sira', 'Jesus son of Sirach']);
add('simon-son-onias', 'Simon, zoon van Onias|Simon, son of Onias|Simon, fils d’Onias', 'Hogepriester in Sirach|High priest in Sirach|Grand prêtre dans le Siracide', 'Sirach looft hogepriester Simon voor zijn zorg voor tempel en stad en beschrijft zijn liturgische optreden.|Sirach praises the high priest Simon for caring for the temple and city and describes his liturgical ministry.|Le Siracide loue le grand prêtre Simon pour son soin du Temple et de la ville et décrit son ministère liturgique.', 'SIR 50:1-21');
const praised = [
  ['enoch', 'Henoch|Enoch|Hénoch', 'Henoch wordt geprezen als voorbeeld van bekering.|Enoch is praised as an example of repentance.|Hénoch est loué comme exemple de repentir.', 'SIR 44:16', 'enoch'],
  ['noah', 'Noach|Noah|Noé', 'Sirach herinnert aan Noachs rechtvaardigheid en het verbond na de vloed.|Sirach recalls Noah’s righteousness and the covenant after the flood.|Le Siracide rappelle la justice de Noé et l’alliance après le déluge.', 'SIR 44:17-19', 'noah'],
  ['abraham', 'Abraham|Abraham|Abraham', 'Sirach looft Abraham om zijn trouw aan het verbond en zijn beproeving.|Sirach praises Abraham’s covenant faithfulness and testing.|Le Siracide loue la fidélité d’Abraham à l’alliance et son épreuve.', 'SIR 44:20-23', 'abraham'],
  ['isaac', 'Isaak|Isaac|Isaac', 'Isaak ontvangt volgens Sirach de zegen die aan Abraham is beloofd.|In Sirach, Isaac receives the blessing promised to Abraham.|Dans le Siracide, Isaac reçoit la bénédiction promise à Abraham.', 'SIR 44:24', 'isaac'],
  ['jacob', 'Jakob|Jacob|Jacob', 'Sirach verbindt Jakob met het verbond, de zegen en het erfdeel van de stammen.|Sirach associates Jacob with the covenant, blessing and the tribes’ inheritance.|Le Siracide associe Jacob à l’alliance, à la bénédiction et à l’héritage des tribus.', 'SIR 44:25-26', 'jacob'],
  ['moses', 'Mozes|Moses|Moïse', 'Sirach looft Mozes als dienaar die Gods geboden aan Israël doorgeeft.|Sirach praises Moses as the servant who gives God’s commandments to Israel.|Le Siracide loue Moïse comme serviteur transmettant les commandements divins à Israël.', 'SIR 45:1-6', 'moses'],
  ['aaron', 'Aäron|Aaron|Aaron', 'Sirach beschrijft Aärons verkiezing, priesterkleding en offerdienst.|Sirach describes Aaron’s calling, priestly garments and sacrificial ministry.|Le Siracide décrit l’élection d’Aaron, ses vêtements sacerdotaux et son service des sacrifices.', 'SIR 45:7-22', 'aaron'],
  ['phinehas', 'Pinechas|Phinehas|Pinhas', 'Sirach prijst Pinechas’ ijver en verbindt hem met een blijvend priesterlijk verbond.|Sirach praises Phinehas’s zeal and connects him with an enduring priestly covenant.|Le Siracide loue le zèle de Pinhas et le relie à une alliance sacerdotale durable.', 'SIR 45:28-30', 'phinehas'],
  ['samuel', 'Samuel|Samuel|Samuel', 'Sirach herinnert aan Samuel als profeet, rechter en trouwe bemiddelaar.|Sirach remembers Samuel as prophet, judge and faithful intercessor.|Le Siracide se souvient de Samuel comme prophète, juge et fidèle intercesseur.', 'SIR 46:16-23', 'step-H8050G'],
  ['nathan', 'Natan, de profeet|Nathan the prophet|Nathan le prophète', 'Sirach noemt de profeet Natan bij David; dit is niet Davids zoon met dezelfde naam.|Sirach mentions the prophet Nathan alongside David; he is not David’s son of the same name.|Le Siracide mentionne le prophète Nathan auprès de David ; il n’est pas le fils homonyme de David.', 'SIR 47:1', 'step-H5416H'],
  ['david', 'David|David|David', 'Sirach looft Davids strijd, lofzang en zorg voor de eredienst.|Sirach praises David’s battles, songs of praise and care for worship.|Le Siracide loue les combats de David, ses chants de louange et son soin du culte.', 'SIR 47:2-14', 'david'],
  ['solomon', 'Salomo|Solomon|Salomon', 'Sirach prijst Salomo’s wijsheid en tempelbouw, maar bekritiseert ook zijn ontrouw.|Sirach praises Solomon’s wisdom and temple building, but also criticizes his unfaithfulness.|Le Siracide loue la sagesse et la construction du Temple par Salomon, mais critique aussi son infidélité.', 'SIR 47:15-26', 'solomon'],
  ['elijah', 'Elia|Elijah|Élie', 'Sirach beschrijft Elia’s vurige profetische optreden en zijn toekomstige verzoenende taak.|Sirach describes Elijah’s fiery prophetic ministry and his future reconciling role.|Le Siracide décrit le ministère prophétique ardent d’Élie et son rôle futur de réconciliation.', 'SIR 48:1-12', 'step-H0452G'],
  ['elisha', 'Elisa|Elisha|Élisée', 'Sirach looft Elisa’s wonderen en zijn onverschrokken optreden.|Sirach praises Elisha’s wonders and fearless ministry.|Le Siracide loue les prodiges d’Élisée et son ministère sans crainte.', 'SIR 48:13-16', 'step-H0477'],
  ['hezekiah', 'Hizkia|Hezekiah|Ézéchias', 'Sirach herinnert aan Hizkia’s verdediging van Jeruzalem en het gebed tijdens de belegering.|Sirach recalls Hezekiah’s defence of Jerusalem and prayer during the siege.|Le Siracide rappelle la défense de Jérusalem par Ézéchias et la prière pendant le siège.', 'SIR 48:19-23', 'hezekiah'],
  ['isaiah', 'Jesaja|Isaiah|Isaïe', 'Sirach beschrijft Jesaja’s profetische visie en zijn troost voor Sion.|Sirach describes Isaiah’s prophetic vision and consolation for Zion.|Le Siracide décrit la vision prophétique d’Isaïe et sa consolation pour Sion.', 'SIR 48:23-28', 'step-H3470A'],
  ['josiah', 'Josia|Josiah|Josias', 'Sirach looft Josia’s herinnering en zijn herstel van de eredienst.|Sirach praises Josiah’s memory and restoration of worship.|Le Siracide loue la mémoire de Josias et sa restauration du culte.', 'SIR 49:1-5', 'josiah'],
  ['jeremiah', 'Jeremia|Jeremiah|Jérémie', 'Sirach herinnert aan Jeremia’s profetische roeping; in 2 Makkabeeën verschijnt hij als voorbidder in een visioen.|Sirach recalls Jeremiah’s prophetic calling; in 2 Maccabees he appears as an intercessor in a vision.|Le Siracide rappelle la vocation prophétique de Jérémie ; dans 2 Maccabées, il apparaît en intercesseur dans une vision.', 'SIR 49:8-9;2MA 15:12-16', 'step-H3414L'],
  ['zerubbabel', 'Zerubbabel|Zerubbabel|Zorobabel', 'Sirach looft Zerubbabel met het beeld van een zegelring.|Sirach praises Zerubbabel through the image of a signet ring.|Le Siracide loue Zorobabel par l’image d’un anneau à cachet.', 'SIR 49:13', 'zerubbabel'],
  ['joshua-high-priest', 'Jozua, zoon van Josadak|Joshua, son of Jozadak|Josué, fils de Josédeq', 'Sirach eert deze hogepriester voor de tempelbouw; de bron noemt hem Jesus, niet Jezus Christus.|Sirach honours this high priest for rebuilding the temple; the source calls him Jesus, not Jesus Christ.|Le Siracide honore ce grand prêtre pour la reconstruction du Temple ; la source le nomme Jesus, sans désigner Jésus Christ.', 'SIR 49:14', 'step-H3091J'],
  ['nehemiah', 'Nehemia|Nehemiah|Néhémie', 'Sirach herinnert aan Nehemia’s herstel van de muren en poorten van Jeruzalem.|Sirach remembers Nehemiah’s restoration of Jerusalem’s walls and gates.|Le Siracide se souvient de la restauration des murs et portes de Jérusalem par Néhémie.', 'SIR 49:15', 'step-H5166H']
];
for (const [key, names, summary, refs, id] of praised) add(key, names, 'Herinnerde Bijbelse persoon|Remembered biblical figure|Figure biblique commémorée', summary, refs, id);

add('baruch', 'Baruch|Baruch|Baruch', 'Schrijver en voorlezer|Writer and reader|Écrivain et lecteur', 'Het boek stelt Baruch, zoon van Neria, voor als schrijver die zijn woorden aan de ballingen voorleest.|The book presents Baruch son of Neriah as the writer who reads his words to the exiles.|Le livre présente Baruch, fils de Nériya, comme l’auteur qui lit ses paroles aux exilés.', 'BAR 1:1-5', 'step-H1263J');
add('jeconiah', 'Jechonja|Jeconiah|Jéchonias', 'Koning in ballingschap|Exiled king|Roi en exil', 'Jechonja, zoon van Jojakim, is aanwezig bij Baruchs voorlezing in Babylon.|Jeconiah son of Jehoiakim is present at Baruch’s reading in Babylon.|Jéchonias, fils de Joaqim, assiste à la lecture de Baruch à Babylone.', 'BAR 1:3-5', 'jeconiah');
add('joakim-baruch', 'Joakim, priester in Baruch|Joakim, priest in Baruch|Joaqim, prêtre dans Baruch', 'Priester in Jeruzalem|Priest in Jerusalem|Prêtre à Jérusalem', 'De ballingen sturen geld naar de priester Joakim, zoon van Helcias; hij is niet Susanna’s echtgenoot.|The exiles send money to the priest Joakim son of Helcias; he is not Susanna’s husband.|Les exilés envoient de l’argent au prêtre Joaqim, fils d’Helcias ; il n’est pas l’époux de Suzanne.', 'BAR 1:6-7');
add('nebuchadnezzar', 'Nebukadnessar|Nebuchadnezzar|Nabuchodonosor', 'Koning van Babylon|King of Babylon|Roi de Babylone', 'Baruch herinnert aan de Babylonische verovering en vraagt gebed voor de koning; ook de brief van Jeremia noemt zijn verovering.|Baruch recalls the Babylonian conquest and asks for prayer for the king; the Letter of Jeremiah also names his conquest.|Baruch rappelle la conquête babylonienne et demande de prier pour le roi ; la Lettre de Jérémie évoque aussi sa conquête.', 'BAR 1:9-12;BAR 6:1-2', 'step-H5019');

// Esther's Greek additions: retain the colophon's names without assigning
// uncertain modern identifications to its Ptolemy and Cleopatra.
add('esther', 'Ester|Esther|Esther', 'Biddende koningin|Praying queen|Reine en prière', 'De aanvullingen geven Ester een uitgebreid gebed en beschrijven haar gevaarlijke optreden voor de koning.|The additions give Esther an extended prayer and describe her dangerous approach to the king.|Les additions donnent à Esther une longue prière et décrivent sa démarche périlleuse auprès du roi.', 'EST 14:1-19;EST 15:1-19', 'step-H0635');
add('mordecai', 'Mordechai|Mordecai|Mardochée', 'Biddende beschermer|Praying protector|Protecteur en prière', 'Mordechai bidt voor zijn volk en duidt zijn droom in de Griekse aanvullingen bij Ester.|Mordecai prays for his people and interprets his dream in the Greek additions to Esther.|Mardochée prie pour son peuple et interprète son songe dans les additions grecques à Esther.', 'EST 10:4-13;EST 13:8-18', 'step-H4782H');
add('haman', 'Haman|Haman|Aman', 'Tegenstander in Ester|Adversary in Esther|Adversaire dans Esther', 'De aanvullingen beschrijven Hamans vijandschap tegenover Mordechai en de ondergang van zijn plan.|The additions describe Haman’s hostility towards Mordecai and the failure of his scheme.|Les additions décrivent l’hostilité d’Aman envers Mardochée et l’échec de son projet.', 'EST 12:6;EST 16:10-14', 'step-H2001');
add('dositheus-esther', 'Dositheüs, overbrenger van Ester|Dositheus, carrier of Esther|Dosithée, porteur d’Esther', 'Overbrenger van het geschrift|Carrier of the text|Porteur du texte', 'Het colofon noemt Dositheüs, die zich priester en leviet noemt, als overbrenger van het geschrift met zijn zoon.|The colophon names Dositheus, who identifies himself as priest and Levite, as bringing the text with his son.|Le colophon nomme Dosithée, qui se dit prêtre et lévite, comme porteur du texte avec son fils.', 'EST 11:1');
add('ptolemy-dositheus', 'Ptolemeüs, zoon van Dositheüs|Ptolemy, son of Dositheus|Ptolémée, fils de Dosithée', 'Overbrenger van het geschrift|Carrier of the text|Porteur du texte', 'Ptolemeüs wordt in het colofon samen met zijn vader Dositheüs genoemd; hij is niet de gelijknamige koning.|Ptolemy is named in the colophon with his father Dositheus; he is not the king of the same name.|Ptolémée est nommé dans le colophon avec son père Dosithée ; il n’est pas le roi homonyme.', 'EST 11:1');
add('lysimachus-esther', 'Lysimachus, vertaler van Ester|Lysimachus, translator of Esther|Lysimaque, traducteur d’Esther', 'Vertaler|Translator|Traducteur', 'Het colofon schrijft de vertaling toe aan Lysimachus, zoon van Ptolemeüs, te Jeruzalem.|The colophon attributes the translation to Lysimachus son of Ptolemy in Jerusalem.|Le colophon attribue la traduction à Lysimaque, fils de Ptolémée, à Jérusalem.', 'EST 11:1');

add('azariah', 'Azarja, metgezel van Daniël|Azariah, companion of Daniel|Azarias, compagnon de Daniel', 'Bidder in de vuuroven|Praying man in the furnace|Homme en prière dans la fournaise', 'Azarja bidt in de oven namens het volk; de katholieke tekst bewaart zijn gebed en het loflied van de drie.|Azariah prays in the furnace on behalf of the people; the Catholic text preserves his prayer and the song of the three.|Azarias prie dans la fournaise au nom du peuple ; le texte catholique conserve sa prière et le cantique des trois.', 'DAN 3:24-45;DAN 3:88', 'step-H5838Z', ['Abednego', 'Azarias']);
add('hananiah', 'Chananja, metgezel van Daniël|Hananiah, companion of Daniel|Hanania, compagnon de Daniel', 'Zanger in de vuuroven|Singer in the furnace|Chanteur dans la fournaise', 'Chananja wordt met Azarja en Misaël genoemd in het loflied uit de vuuroven.|Hananiah is named with Azariah and Mishael in the song from the furnace.|Hanania est nommé avec Azarias et Mishaël dans le cantique de la fournaise.', 'DAN 3:88-90', 'step-H2608T', ['Shadrach', 'Ananias']);
add('mishael', 'Misaël, metgezel van Daniël|Mishael, companion of Daniel|Mishaël, compagnon de Daniel', 'Zanger in de vuuroven|Singer in the furnace|Chanteur dans la fournaise', 'Misaël wordt met zijn metgezellen opgeroepen God te loven omdat zij uit het vuur zijn gered.|Mishael and his companions are called to praise God for their rescue from the fire.|Mishaël et ses compagnons sont appelés à louer Dieu pour leur délivrance du feu.', 'DAN 3:88-90', 'step-H4332I', ['Meshach', 'Misael']);
add('susanna', 'Susanna|Susanna|Suzanne', 'Vals beschuldigde vrouw|Falsely accused woman|Femme faussement accusée', 'Susanna weigert de dwang van twee oudsten; Daniël ontmaskert hun valse getuigenis en redt haar leven.|Susanna refuses the coercion of two elders; Daniel exposes their false testimony and saves her life.|Suzanne refuse la contrainte de deux anciens ; Daniel démasque leur faux témoignage et lui sauve la vie.', 'DAN 13:1-4;DAN 13:22-23;DAN 13:42-63');
add('joakim-susanna', 'Joakim, man van Susanna|Joakim, husband of Susanna|Joaqim, époux de Suzanne', 'Echtgenoot van Susanna|Husband of Susanna|Époux de Suzanne', 'Joakim is de welgestelde echtgenoot van Susanna in Babylon; zijn huis en tuin vormen de plaats van het verhaal.|Joakim is Susanna’s wealthy husband in Babylon; his house and garden form the setting of the story.|Joaqim est le riche époux de Suzanne à Babylone ; sa maison et son jardin constituent le cadre du récit.', 'DAN 13:1-4;DAN 13:63');
add('helcias-susanna', 'Chelkia, vader van Susanna|Helcias, father of Susanna|Helcias, père de Suzanne', 'Vader van Susanna|Father of Susanna|Père de Suzanne', 'Susanna wordt dochter van Chelkia genoemd; haar ouders hebben haar in de wet van Mozes opgevoed.|Susanna is called the daughter of Helcias; her parents raised her in the law of Moses.|Suzanne est appelée fille d’Helcias ; ses parents l’ont élevée dans la loi de Moïse.', 'DAN 13:2-3;DAN 13:63', null, ['Helcias']);
add('daniel', 'Daniël|Daniel|Daniel', 'Profeet en verdediger|Prophet and defender|Prophète et défenseur', 'In de aanvullingen verdedigt Daniël Susanna en ontmaskert hij de verering van Bel en de draak.|In the additions Daniel defends Susanna and exposes the worship of Bel and the dragon.|Dans les additions, Daniel défend Suzanne et démasque le culte de Bel et du dragon.', 'DAN 13:45-62;DAN 14:1-27', 'step-H1840G');
add('habakkuk', 'Habakuk|Habakkuk|Habacuc', 'Profeet die voedsel brengt|Prophet bringing food|Prophète apportant de la nourriture', 'In Bel en de draak wordt Habakuk naar Babylon gebracht om Daniël in de leeuwenkuil te voeden.|In Bel and the Dragon Habakkuk is brought to Babylon to feed Daniel in the lions’ den.|Dans Bel et le Dragon, Habacuc est transporté à Babylone pour nourrir Daniel dans la fosse aux lions.', 'DAN 14:32-38', 'step-H2265');
add('cyrus', 'Cyrus|Cyrus|Cyrus', 'Koning in Bel en de draak|King in Bel and the Dragon|Roi dans Bel et le Dragon', 'Na de overgang van Astyages naar Cyrus volgt het verhaal over de koning, Daniël, Bel en de draak.|After the transition from Astyages to Cyrus comes the story of the king, Daniel, Bel and the dragon.|Après la transition d’Astyage à Cyrus vient le récit du roi, de Daniel, de Bel et du dragon.', 'DAN 13:65;DAN 14:1-6;DAN 14:23-27', 'step-H3566');
add('astyages', 'Astyages|Astyages|Astyage', 'Koning vóór Cyrus|King before Cyrus|Roi avant Cyrus', 'Het slot van Daniël 13 vermeldt Astyages’ dood en de troonsopvolging door Cyrus.|The end of Daniel 13 records Astyages’s death and Cyrus’s succession.|La fin de Daniel 13 rapporte la mort d’Astyage et l’avènement de Cyrus.', 'DAN 13:65');

// Maccabees: contextual identifiers protect the several Eleazars, Jasons,
// Ptolemies, Simons, Apolloniuses and Lysimachuses from name-only merging.
add('mattathias', 'Mattatias|Mattathias|Mattathias', 'Priester en opstandsleider|Priest and revolt leader|Prêtre et chef de révolte', 'Mattatias en zijn vijf zonen staan aan het begin van het verzet dat 1 Makkabeeën beschrijft.|Mattathias and his five sons stand at the beginning of the resistance described in 1 Maccabees.|Mattathias et ses cinq fils sont à l’origine de la résistance décrite dans 1 Maccabées.', '1MA 2:1-7;1MA 2:19-28', null, ['Mathathias']);
add('john-gaddi', 'Johannes Gaddi|John Gaddi|Jean Gaddi', 'Zoon van Mattatias|Son of Mattathias|Fils de Mattathias', 'Johannes Gaddi wordt als een van Mattatias’ vijf zonen voorgesteld.|John Gaddi is introduced as one of Mattathias’s five sons.|Jean Gaddi est présenté comme l’un des cinq fils de Mattathias.', '1MA 2:2', null, ['John Gaddis']);
add('simon-maccabeus', 'Simon Makkabeüs|Simon Maccabeus|Simon Maccabée', 'Leider en hogepriester|Leader and high priest|Chef et grand prêtre', 'Simon, zoon van Mattatias, leidt het volk en wordt later door Ptolemeüs, zoon van Abubus, gedood.|Simon son of Mattathias leads the people and is later killed by Ptolemy son of Abubus.|Simon, fils de Mattathias, dirige le peuple et est ensuite tué par Ptolémée, fils d’Aboubos.', '1MA 2:3;1MA 14:35-43;1MA 16:11-16', null, ['Simon Thassi', 'Simon Thasi']);
add('judas-maccabeus', 'Judas Makkabeüs|Judas Maccabeus|Judas Maccabée', 'Legerleider|Military leader|Chef militaire', 'Judas volgt zijn vader Mattatias op en leidt het verzet en de herinwijding van de tempel.|Judas succeeds his father Mattathias and leads the resistance and rededication of the temple.|Judas succède à son père Mattathias et dirige la résistance et la nouvelle dédicace du Temple.', '1MA 2:4;1MA 3:1-9;1MA 4:36-59', null, ['Judas Machabeus']);
add('eleazar-avaran', 'Eleazar Avaran|Eleazar Avaran|Éléazar Avarân', 'Strijder, zoon van Mattatias|Warrior, son of Mattathias|Combattant, fils de Mattathias', 'Eleazar is een zoon van Mattatias en sterft tijdens een aanval op een oorlogsolifant; hij is niet de oudere martelaar uit 2 Makkabeeën.|Eleazar is a son of Mattathias and dies attacking a war elephant; he is not the elderly martyr of 2 Maccabees.|Éléazar est un fils de Mattathias et meurt en attaquant un éléphant de guerre ; il n’est pas le vieux martyr de 2 Maccabées.', '1MA 2:5;1MA 6:43-46', null, ['Eleazar Abaron']);
add('jonathan-maccabeus', 'Jonatan Makkabeüs|Jonathan Maccabeus|Jonathan Maccabée', 'Leider en hogepriester|Leader and high priest|Chef et grand prêtre', 'Jonatan, zoon van Mattatias, leidt na Judas het verzet en ontvangt het hogepriesterschap.|Jonathan son of Mattathias leads the resistance after Judas and receives the high priesthood.|Jonathan, fils de Mattathias, dirige la résistance après Judas et reçoit le grand sacerdoce.', '1MA 2:5;1MA 9:28-31;1MA 10:18-21', null, ['Jonathan Apphus']);
add('antiochus-iv', 'Antiochus IV Epifanes|Antiochus IV Epiphanes|Antiochos IV Épiphane', 'Seleucidische koning|Seleucid king|Roi séleucide', 'Antiochus, bijgenaamd de Illustere, voert de vervolging en dwangmaatregelen in die het verzet aanwakkeren.|Antiochus, called the Illustrious, imposes the persecution and coercive measures that provoke resistance.|Antiochos, surnommé l’Illustre, impose la persécution et les mesures coercitives qui provoquent la résistance.', '1MA 1:11;1MA 1:43-57', null, ['Antiochus Epiphanes', 'Antiochus Illustrious']);
add('alexander-great', 'Alexander de Grote|Alexander the Great|Alexandre le Grand', 'Macedonische koning|Macedonian king|Roi macédonien', '1 Makkabeeën opent met Alexanders veroveringen en de verdeling van zijn rijk na zijn dood.|1 Maccabees opens with Alexander’s conquests and the division of his kingdom after his death.|1 Maccabées commence par les conquêtes d’Alexandre et le partage de son royaume après sa mort.', '1MA 1:1-10');
add('apollonius-samaria', 'Apollonius van Samaria|Apollonius of Samaria|Apollonius de Samarie', 'Tegenstander van Judas|Opponent of Judas|Adversaire de Judas', 'Apollonius verzamelt een leger uit Samaria maar wordt door Judas verslagen.|Apollonius gathers an army from Samaria but is defeated by Judas.|Apollonius rassemble une armée de Samarie mais est vaincu par Judas.', '1MA 3:10-12');
add('seron', 'Seron|Seron|Sérôn', 'Syrische bevelhebber|Syrian commander|Commandant syrien', 'Seron trekt tegen Judas op maar wordt bij Bethoron verslagen.|Seron marches against Judas but is defeated at Bethoron.|Sérôn marche contre Judas mais est vaincu à Beth-Horôn.', '1MA 3:13-24');
add('lysias', 'Lysias|Lysias|Lysias', 'Regent en bevelhebber|Regent and commander|Régent et commandant', 'Antiochus stelt Lysias aan als bestuurder en voogd van zijn zoon; Lysias voert oorlog tegen Judas.|Antiochus appoints Lysias as administrator and guardian of his son; Lysias wages war against Judas.|Antiochos nomme Lysias administrateur et tuteur de son fils ; Lysias fait la guerre à Judas.', '1MA 3:32-35;1MA 4:28-35');
add('ptolemy-dorymenes', 'Ptolemeüs, zoon van Dorymenes|Ptolemy, son of Dorymenes|Ptolémée, fils de Dorymène', 'Koninklijke bevelhebber|Royal commander|Commandant royal', 'Lysias kiest Ptolemeüs, zoon van Dorymenes, samen met Nikanor en Gorgias voor de veldtocht.|Lysias chooses Ptolemy son of Dorymenes with Nicanor and Gorgias for the campaign.|Lysias choisit Ptolémée, fils de Dorymène, avec Nicanor et Gorgias pour la campagne.', '1MA 3:38-41');
add('nicanor', 'Nikanor|Nicanor|Nicanor', 'Bevelhebber tegen Judas|Commander opposing Judas|Commandant opposé à Judas', 'Nikanor verschijnt onder de koninklijke bevelhebbers; 2 Makkabeeën beschrijft zijn nederlaag als bevrijding voor het volk.|Nicanor appears among the royal commanders; 2 Maccabees describes his defeat as deliverance for the people.|Nicanor figure parmi les commandants royaux ; 2 Maccabées décrit sa défaite comme une délivrance pour le peuple.', '1MA 3:38;2MA 15:25-36');
add('gorgias', 'Gorgias|Gorgias|Gorgias', 'Legerbevelhebber|Army commander|Chef de l’armée', 'Gorgias probeert Judas met een nachtelijke aanval te verrassen.|Gorgias attempts to surprise Judas with a night attack.|Gorgias tente de surprendre Judas par une attaque nocturne.', '1MA 3:38;1MA 4:1-5');
add('timothy-ammon', 'Timoteüs in 1 Makkabeeën|Timothy in 1 Maccabees|Timothée dans 1 Maccabées', 'Bevelhebber van de Ammonieten|Commander of the Ammonites|Commandant des Ammonites', '1 Makkabeeën beschrijft Timoteüs als aanvoerder van de Ammonieten die door Judas wordt bestreden.|1 Maccabees describes Timothy as the Ammonite commander opposed by Judas.|1 Maccabées décrit Timothée comme le commandant ammonite combattu par Judas.', '1MA 5:6-8');
add('antiochus-v', 'Antiochus V Eupator|Antiochus V Eupator|Antiochos V Eupator', 'Jonge Seleucidische koning|Young Seleucid king|Jeune roi séleucide', 'Lysias stelt Antiochus, de jonge zoon van de overleden koning, als koning aan en noemt hem Eupator.|Lysias installs Antiochus, the late king’s young son, as king and calls him Eupator.|Lysias établit comme roi Antiochos, jeune fils du roi défunt, et le nomme Eupator.', '1MA 6:17');
add('demetrius-i', 'Demetrius I|Demetrius I|Démétrios Ier', 'Seleucidische koning|Seleucid king|Roi séleucide', 'Demetrius komt uit Rome, neemt de macht over en steunt Alcimus en Bacchides.|Demetrius comes from Rome, takes power and supports Alcimus and Bacchides.|Démétrios arrive de Rome, prend le pouvoir et soutient Alkime et Bacchidès.', '1MA 7:1-9');
add('alcimus', 'Alcimus|Alcimus|Alkime', 'Mededinger om het hogepriesterschap|Claimant to the high priesthood|Prétendant au grand sacerdoce', 'Alcimus vraagt Demetrius om steun voor het hogepriesterschap en gaat met Bacchides naar Judea.|Alcimus asks Demetrius to support his claim to the high priesthood and goes to Judea with Bacchides.|Alkime demande à Démétrios d’appuyer sa prétention au grand sacerdoce et part en Judée avec Bacchidès.', '1MA 7:5-9');
add('bacchides', 'Bacchides|Bacchides|Bacchidès', 'Koninklijke bevelhebber|Royal commander|Commandant royal', 'Demetrius stuurt Bacchides met Alcimus naar Judea om zijn beleid af te dwingen.|Demetrius sends Bacchides with Alcimus to Judea to enforce his policy.|Démétrios envoie Bacchidès avec Alkime en Judée pour imposer sa politique.', '1MA 7:8-9;1MA 9:1-6');
add('eupolemus', 'Eupolemus|Eupolemus|Eupolème', 'Gezant naar Rome|Envoy to Rome|Envoyé à Rome', 'Judas stuurt Eupolemus, zoon van Johannes, met Jason naar Rome om een verbond te sluiten.|Judas sends Eupolemus son of John with Jason to Rome to establish an alliance.|Judas envoie Eupolème, fils de Jean, avec Jason à Rome pour établir une alliance.', '1MA 8:17-20');
add('jason-envoy', 'Jason, zoon van Eleazar|Jason, son of Eleazar|Jason, fils d’Éléazar', 'Gezant naar Rome|Envoy to Rome|Envoyé à Rome', 'Deze Jason reist met Eupolemus naar Rome; hij is niet de hogepriester of de schrijver uit Cyrene.|This Jason travels to Rome with Eupolemus; he is neither the high priest nor the writer from Cyrene.|Ce Jason voyage à Rome avec Eupolème ; il n’est ni le grand prêtre ni l’écrivain de Cyrène.', '1MA 8:17-20');
add('alexander-balas', 'Alexander Balas|Alexander Balas|Alexandre Balas', 'Rivaal om het koningschap|Rival claimant to kingship|Rival pour la royauté', 'Alexander verschijnt als tegenstander van Demetrius en geeft Jonatan het hogepriesterschap.|Alexander appears as Demetrius’s rival and grants Jonathan the high priesthood.|Alexandre apparaît comme rival de Démétrios et accorde à Jonathan le grand sacerdoce.', '1MA 10:1-3;1MA 10:18-21');
add('cleopatra-alexander', 'Cleopatra, vrouw van Alexander|Cleopatra, wife of Alexander|Cléopâtre, épouse d’Alexandre', 'Egyptische prinses|Egyptian princess|Princesse égyptienne', 'Ptolemeüs geeft zijn dochter Cleopatra aan Alexander als vrouw; zij is niet zonder meer de Cleopatra uit Esters colofon.|Ptolemy gives his daughter Cleopatra to Alexander in marriage; she is not automatically identified with the Cleopatra of Esther’s colophon.|Ptolémée donne sa fille Cléopâtre à Alexandre en mariage ; elle n’est pas identifiée automatiquement à la Cléopâtre du colophon d’Esther.', '1MA 10:57-58');
add('demetrius-ii', 'Demetrius II|Demetrius II|Démétrios II', 'Zoon en opvolger van Demetrius|Son and successor of Demetrius|Fils et successeur de Démétrios', 'Demetrius, zoon van Demetrius, trekt het land binnen en strijdt om het koningschap.|Demetrius son of Demetrius enters the country and contests the kingship.|Démétrios, fils de Démétrios, entre dans le pays et dispute la royauté.', '1MA 10:67-69;1MA 11:19-21');
add('tryphon', 'Tryfon|Tryphon|Tryphon', 'Machtszoeker|Contender for power|Prétendant au pouvoir', 'Tryfon steunt eerst de jonge Antiochus en neemt later zelf de macht over.|Tryphon first supports the young Antiochus and later seizes power himself.|Tryphon soutient d’abord le jeune Antiochos puis prend lui-même le pouvoir.', '1MA 11:39-40;1MA 13:31-32');
add('antiochus-vi', 'Antiochus VI, zoon van Alexander|Antiochus VI, son of Alexander|Antiochos VI, fils d’Alexandre', 'Kindkoning|Child king|Enfant roi', 'Tryfon brengt de jonge Antiochus, zoon van Alexander, naar voren als koning.|Tryphon advances the young Antiochus son of Alexander as king.|Tryphon présente le jeune Antiochos, fils d’Alexandre, comme roi.', '1MA 11:39-40;1MA 11:54-57');
add('numenius', 'Numenius|Numenius|Nouménios', 'Gezant|Envoy|Envoyé', 'Numenius, zoon van Antiochus, wordt met Antipater als gezant uitgezonden.|Numenius son of Antiochus is sent as an envoy with Antipater.|Nouménios, fils d’Antiochos, est envoyé comme ambassadeur avec Antipater.', '1MA 12:16;1MA 14:22');
add('antipater', 'Antipater|Antipater|Antipater', 'Gezant|Envoy|Envoyé', 'Antipater, zoon van Jason, reist met Numenius als gezant.|Antipater son of Jason travels as an envoy with Numenius.|Antipater, fils de Jason, voyage comme ambassadeur avec Nouménios.', '1MA 12:16;1MA 14:22');
add('antiochus-vii', 'Antiochus VII|Antiochus VII|Antiochos VII', 'Seleucidische koning|Seleucid king|Roi séleucide', 'Antiochus, zoon van koning Demetrius, schrijft Simon over zijn aanspraak op het koningschap.|Antiochus son of King Demetrius writes to Simon about his claim to the kingship.|Antiochos, fils du roi Démétrios, écrit à Simon au sujet de sa prétention à la royauté.', '1MA 15:1-9');
add('cendebeus', 'Kendebeüs|Cendebeus|Kendébée', 'Bevelhebber aan de kust|Coastal commander|Commandant du littoral', 'De koning stelt Kendebeüs aan als bevelhebber aan de kust om Judea aan te vallen.|The king appoints Cendebeus as coastal commander to attack Judea.|Le roi nomme Kendébée commandant du littoral pour attaquer la Judée.', '1MA 15:38-41');
add('john-hyrcanus', 'Johannes, zoon van Simon|John, son of Simon|Jean, fils de Simon', 'Bevelhebber en opvolger|Commander and successor|Commandant et successeur', 'Johannes strijdt voor zijn vader Simon en ontkomt aan Ptolemeüs’ moordplan.|John fights for his father Simon and escapes Ptolemy’s murder plot.|Jean combat pour son père Simon et échappe au complot meurtrier de Ptolémée.', '1MA 16:1-10;1MA 16:21-24', null, ['John Hyrcanus', 'Johannes Hyrkanus']);
add('ptolemy-abubus', 'Ptolemeüs, zoon van Abubus|Ptolemy, son of Abubus|Ptolémée, fils d’Aboubos', 'Bestuurder van Jericho|Governor of Jericho|Gouverneur de Jéricho', 'Ptolemeüs, Simons schoonzoon, laat Simon en twee van diens zonen tijdens een maaltijd doden.|Ptolemy, Simon’s son-in-law, has Simon and two of his sons killed during a meal.|Ptolémée, gendre de Simon, fait tuer Simon et deux de ses fils pendant un repas.', '1MA 16:11-17');

add('jason-cyrene', 'Jason van Cyrene|Jason of Cyrene|Jason de Cyrène', 'Geschiedschrijver|Historian|Historien', '2 Makkabeeën presenteert zich als samenvatting van Jasons vijf boeken; hij is niet de gelijknamige hogepriester.|2 Maccabees presents itself as a summary of Jason’s five books; he is distinct from the high priest of the same name.|2 Maccabées se présente comme un résumé des cinq livres de Jason ; il se distingue du grand prêtre homonyme.', '2MA 2:24-29');
add('onias-iii', 'Onias, hogepriester|Onias the high priest|Onias le grand prêtre', 'Hogepriester|High priest|Grand prêtre', 'Onias verdedigt de tempelschat en wordt later door Andronicus gedood.|Onias defends the temple treasury and is later killed by Andronicus.|Onias défend le trésor du Temple et est ensuite tué par Andronique.', '2MA 3:1-12;2MA 4:33-35');
add('seleucus', 'Seleucus|Seleucus|Séleucos', 'Koning van Azië|King of Asia|Roi d’Asie', 'Seleucus draagt bij aan de tempeldienst, maar stuurt Heliodorus wanneer hij over het geld in de tempel hoort.|Seleucus supports temple worship but sends Heliodorus after hearing about the money in the temple.|Séleucos soutient le culte du Temple mais envoie Héliodore après avoir entendu parler de l’argent qui s’y trouve.', '2MA 3:3-7');
add('simon-temple', 'Simon, tempelbestuurder|Simon, temple administrator|Simon, administrateur du Temple', 'Tempelbestuurder|Temple administrator|Administrateur du Temple', 'Deze Simon raakt met Onias in conflict en bericht Apollonius over de rijkdom van de tempel.|This Simon quarrels with Onias and informs Apollonius about the temple’s wealth.|Ce Simon entre en conflit avec Onias et informe Apollonius de la richesse du Temple.', '2MA 3:4-6');
add('apollonius-tharseas', 'Apollonius, zoon van Tharseas|Apollonius, son of Tharseas|Apollonius, fils de Tharséas', 'Regionale bestuurder|Regional governor|Gouverneur régional', 'Apollonius, zoon van Tharseas, ontvangt Simons bericht over de tempelschat en informeert de koning.|Apollonius son of Tharseas receives Simon’s report about the temple treasury and informs the king.|Apollonius, fils de Tharséas, reçoit le rapport de Simon sur le trésor du Temple et informe le roi.', '2MA 3:5-7');
add('heliodorus', 'Heliodorus|Heliodorus|Héliodore', 'Koninklijke gezant|Royal envoy|Envoyé royal', 'Heliodorus probeert de tempelschat op te eisen, maar wordt in het verhaal door een hemelse verschijning tegengehouden.|Heliodorus tries to seize the temple treasury but is stopped in the narrative by a heavenly apparition.|Héliodore tente de saisir le trésor du Temple, mais une apparition céleste l’en empêche dans le récit.', '2MA 3:7-14;2MA 3:23-35');
add('hyrcanus-tobias', 'Hyrkanus, zoon van Tobias|Hyrcanus, son of Tobias|Hyrcan, fils de Tobie', 'Eigenaar van toevertrouwd geld|Owner of deposited funds|Propriétaire de fonds déposés', 'Een deel van het geld in de tempel behoort volgens Onias aan Hyrkanus, zoon van Tobias.|According to Onias, part of the money in the temple belongs to Hyrcanus son of Tobias.|Selon Onias, une partie de l’argent du Temple appartient à Hyrcan, fils de Tobie.', '2MA 3:11');
add('jason-high-priest', 'Jason, broer van Onias|Jason, brother of Onias|Jason, frère d’Onias', 'Mededinger om het hogepriesterschap|Claimant to the high priesthood|Prétendant au grand sacerdoce', 'Jason, broer van Onias, verwerft het hogepriesterschap door een geldelijke belofte aan de koning.|Jason, Onias’s brother, obtains the high priesthood by promising money to the king.|Jason, frère d’Onias, obtient le grand sacerdoce en promettant de l’argent au roi.', '2MA 4:7-13');
add('menelaus', 'Menelaüs|Menelaus|Ménélas', 'Mededinger om het hogepriesterschap|Claimant to the high priesthood|Prétendant au grand sacerdoce', 'Menelaüs overbiedt Jason om het hogepriesterschap te verkrijgen en raakt betrokken bij de tempelroof.|Menelaus outbids Jason to obtain the high priesthood and becomes involved in the plundering of the temple.|Ménélas surenchérit sur Jason pour obtenir le grand sacerdoce et participe au pillage du Temple.', '2MA 4:23-27;2MA 4:32-34');
add('sostratus', 'Sostratus|Sostratus|Sostrate', 'Koninklijke ambtenaar|Royal official|Fonctionnaire royal', 'Sostratus eist betaling van Menelaüs en moet met hem voor de koning verschijnen.|Sostratus demands payment from Menelaus and must appear with him before the king.|Sostrate exige le paiement de Ménélas et doit comparaître avec lui devant le roi.', '2MA 4:27-29');
add('lysimachus-menelaus', 'Lysimachus, broer van Menelaüs|Lysimachus, brother of Menelaus|Lysimaque, frère de Ménélas', 'Plaatsvervanger en tempelrover|Deputy and temple plunderer|Suppléant et pilleur du Temple', 'Lysimachus vervangt Menelaüs en wordt gedood nadat zijn tempelroof tot verzet leidt.|Lysimachus acts for Menelaus and is killed after his plundering of the temple provokes resistance.|Lysimaque remplace Ménélas et est tué après que son pillage du Temple a provoqué une résistance.', '2MA 4:29;2MA 4:39-42');
add('andronicus', 'Andronicus|Andronicus|Andronique', 'Koninklijke plaatsvervanger|Royal deputy|Représentant royal', 'Andronicus lokt Onias uit zijn toevluchtsoord en doodt hem.|Andronicus lures Onias from his refuge and kills him.|Andronique attire Onias hors de son refuge et le tue.', '2MA 4:31-38');
add('eleazar-martyr', 'Eleazar, de oudere schriftgeleerde|Eleazar the elderly scribe|Éléazar, le vieux scribe', 'Martelaar|Martyr|Martyr', 'De oudere Eleazar weigert zowel verboden voedsel als een schijnbekering; hij is niet Mattatias’ zoon Eleazar.|The elderly Eleazar refuses both forbidden food and a pretended conversion; he is distinct from Mattathias’s son Eleazar.|Le vieil Éléazar refuse la nourriture interdite et une conversion simulée ; il est distinct du fils de Mattathias.', '2MA 6:18-31');
add('mother-seven-sons', 'Moeder van de zeven zonen|Mother of the seven sons|Mère des sept fils', 'Naamloze moeder en getuige|Unnamed mother and witness|Mère anonyme et témoin', 'De naamloze moeder moedigt haar zeven zonen aan trouw te blijven en spreekt over schepping en opstanding.|The unnamed mother encourages her seven sons to remain faithful and speaks about creation and resurrection.|La mère anonyme encourage ses sept fils à rester fidèles et parle de la création et de la résurrection.', '2MA 7:1;2MA 7:20-29;2MA 7:41');
add('dositheus-captain', 'Dositheüs, bevelhebber van Judas|Dositheus, commander under Judas|Dosithée, commandant de Judas', 'Legerbevelhebber|Army commander|Chef de l’armée', 'Dositheüs en Sosipater worden als bevelhebbers van Judas genoemd; deze Dositheüs is niet de overbrenger van Ester.|Dositheus and Sosipater are named as commanders under Judas; this Dositheus is distinct from the carrier of Esther.|Dosithée et Sosipater sont nommés comme commandants de Judas ; ce Dosithée se distingue du porteur d’Esther.', '2MA 12:19;2MA 12:24');
add('sosipater', 'Sosipater|Sosipater|Sosipatros', 'Legerbevelhebber|Army commander|Chef de l’armée', 'Sosipater wordt met Dositheüs genoemd bij Judas’ bevelhebbers en de gevangenneming van Timoteüs.|Sosipater is named with Dositheus among Judas’s commanders and in the capture of Timothy.|Sosipatros est nommé avec Dosithée parmi les commandants de Judas et lors de la capture de Timothée.', '2MA 12:19;2MA 12:24');
add('razis', 'Razis|Razis|Razis', 'Oudste van Jeruzalem|Elder of Jerusalem|Ancien de Jérusalem', 'Razis wordt als een gerespecteerde oudste beschreven; Nikanor stuurt soldaten om hem gevangen te nemen.|Razis is described as a respected elder; Nicanor sends soldiers to arrest him.|Razis est décrit comme un ancien respecté ; Nicanor envoie des soldats pour l’arrêter.', '2MA 14:37-40', null, ['Razias']);

// Display names deliberately qualify namesakes. Keep the edition's short forms
// available too, so cited occurrences resolve to the right person rather than a
// different atlas namesake. Shared forms remain separate candidate identities.
const sourceAliases = {
  tobit: ['Tobias'], 'anna-tobit': ['Anna'], 'anna-raguel': ['Anna'],
  'sarah-tobit': ['Sara'], 'achior-tobit': ['Achior'], 'achior-judith': ['Achior'],
  'simon-son-onias': ['Simon'], 'ben-sira': ['Jesus'],
  'joakim-baruch': ['Joakim'], 'joakim-susanna': ['Joakim'],
  'dositheus-esther': ['Dositheus'], 'dositheus-captain': ['Dositheus'],
  'lysimachus-esther': ['Lysimachus'], 'lysimachus-menelaus': ['Lysimachus'],
  'john-gaddi': ['John'], 'john-hyrcanus': ['John'],
  'simon-maccabeus': ['Simon'], 'simon-temple': ['Simon'],
  'judas-maccabeus': ['Judas'], 'jonathan-maccabeus': ['Jonathan'],
  'eleazar-avaran': ['Eleazar'], 'eleazar-martyr': ['Eleazar'],
  'jason-envoy': ['Jason'], 'jason-high-priest': ['Jason'], 'jason-cyrene': ['Jason'],
  'onias-iii': ['Onias'], 'hyrcanus-tobias': ['Hircanus', 'Hyrcanus'],
  'apollonius-samaria': ['Apollonius'], 'apollonius-tharseas': ['Apollonius'],
  'timothy-ammon': ['Timotheus'], 'cleopatra-alexander': ['Cleopatra'],
  'alexander-great': ['Alexander'], 'alexander-balas': ['Alexander']
};
// Do not add bare dynastic names here: passages such as 1MA 1:11 and
// 10:67 name a king and his identically named father in the same verse.
// Verse-level evidence cannot resolve those individual word occurrences.
for (const row of rows) row.aliases.push(...(sourceAliases[row.key] || []));
module.exports = rows;
